/**
 * The subset of named character references decoded by `decodeHtmlEntities`.
 * @type {Map<string, string>}
 */
const NAMED_CHAR_REFERENCES = new Map([
	["amp", "&"],
	["lt", "<"],
	["gt", ">"],
	["quot", '"'],
	["apos", "'"],
	["nbsp", " "]
]);

// Matches a single HTML character reference: a decimal numeric reference
// (`&#65;`), a hexadecimal numeric reference (`&#x41;` / `&#X41;`) or a named
// reference (`&amp;`). The trailing semicolon is required so bare ampersands
// and truncated references (`&`, `&amp`) are left untouched. Empty numeric
// references (`&#;`, `&#x;`) don't match because at least one digit is
// required.
const HTML_CHAR_REFERENCE_REGEXP =
	/&(?:#(\d+)|#[xX]([\da-fA-F]+)|([a-zA-Z][a-zA-Z0-9]*));/g;

/**
 * Decodes HTML character references in a raw string back to their character
 * values. Only the small set of named references in `NAMED_CHAR_REFERENCES`
 * plus decimal/hexadecimal numeric references are recognized. Unknown named
 * references, malformed/empty numeric references and bare ampersands are left
 * unchanged.
 * @param {string} input raw string that may contain HTML character references
 * @returns {string} the decoded string
 */
const decodeHtmlEntities = (input) => {
	// Fast path: nothing to decode without an ampersand.
	if (!input.includes("&")) return input;

	return input.replace(
		HTML_CHAR_REFERENCE_REGEXP,
		(match, decimal, hexadecimal, name) => {
			if (decimal !== undefined) {
				const codePoint = Number.parseInt(decimal, 10);
				if (codePoint > 0x10ffff) return match;
				return String.fromCodePoint(codePoint);
			}
			if (hexadecimal !== undefined) {
				const codePoint = Number.parseInt(hexadecimal, 16);
				if (codePoint > 0x10ffff) return match;
				return String.fromCodePoint(codePoint);
			}
			const decoded = NAMED_CHAR_REFERENCES.get(name);
			return decoded !== undefined ? decoded : match;
		}
	);
};

